import java.util.HashMap;
import java.util.Map;

public class Main {
    static int bruteForce(String s) {
        int best = 0;
        for (int i = 0; i < s.length(); i++) {
            boolean[] seen = new boolean[128];
            int len = 0;
            for (int j = i; j < s.length() && !seen[s.charAt(j)]; j++) {
                seen[s.charAt(j)] = true;
                len++;
            }
            best = Math.max(best, len);
        }
        return best;
    }

    static int lengthOfLongest(String s, boolean trace) {
        Map<Character, Integer> last = new HashMap<>();
        int left = 0, best = 0;
        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            Integer prev = last.get(c);
            if (prev != null && prev >= left) {
                left = prev + 1;
            }
            last.put(c, right);
            best = Math.max(best, right - left + 1);
            if (trace) {
                System.out.println("right=" + right + " c=" + c + " left=" + left
                    + " window=" + s.substring(left, right + 1) + " best=" + best);
            }
        }
        return best;
    }

    public static void main(String[] args) {
        lengthOfLongest("abcabcbb", true);
        String[] tests = {"", "a", "bbbbb", "pwwkew", "abba", "tmmzuxt"};
        for (String t : tests) {
            System.out.println("\"" + t + "\" -> " + lengthOfLongest(t, false)
                + " (brute " + bruteForce(t) + ")");
        }
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

public class Main {
    static int countIslands(char[][] grid) {
        if (grid.length == 0) return 0;
        int rows = grid.length, cols = grid[0].length, count = 0;
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '1') continue;
                count++;
                grid[r][c] = '0';
                Deque<int[]> queue = new ArrayDeque<>();
                queue.add(new int[]{r, c});
                while (!queue.isEmpty()) {
                    int[] cur = queue.poll();
                    for (int[] d : dirs) {
                        int nr = cur[0] + d[0], nc = cur[1] + d[1];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '1') {
                            grid[nr][nc] = '0';
                            queue.add(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
        return count;
    }

    static char[][] parse(String... rows) {
        char[][] g = new char[rows.length][];
        for (int i = 0; i < rows.length; i++) g[i] = rows[i].toCharArray();
        return g;
    }

    public static void main(String[] args) {
        System.out.println(countIslands(parse("11000", "11000", "00100", "00011")));
        System.out.println(countIslands(parse("111", "010", "111")));
        System.out.println(countIslands(parse("0")));
        System.out.println(countIslands(parse("101", "010", "101")));
        System.out.println(countIslands(new char[0][0]));
    }
}

import java.util.Arrays;

public class Main {
    static int brute(int[] coins, int amount) {
        if (amount == 0) return 0;
        if (amount < 0) return -1;
        int best = Integer.MAX_VALUE;
        for (int c : coins) {
            int sub = brute(coins, amount - c);
            if (sub >= 0) best = Math.min(best, sub + 1);
        }
        return best == Integer.MAX_VALUE ? -1 : best;
    }

    static int coinChange(int[] coins, int amount, boolean trace) {
        int[] dp = new int[amount + 1];
        Arrays.fill(dp, amount + 1);
        dp[0] = 0;
        for (int a = 1; a <= amount; a++) {
            for (int c : coins) {
                if (c <= a) dp[a] = Math.min(dp[a], dp[a - c] + 1);
            }
        }
        if (trace) System.out.println(Arrays.toString(dp));
        return dp[amount] > amount ? -1 : dp[amount];
    }

    public static void main(String[] args) {
        System.out.println(coinChange(new int[]{1, 2, 5}, 11, true));
        System.out.println(coinChange(new int[]{2}, 3, false));
        System.out.println(coinChange(new int[]{1}, 0, false));
        System.out.println(coinChange(new int[]{186, 419, 83, 408}, 6249, false));
        System.out.println(brute(new int[]{1, 2, 5}, 11));
        System.out.println(coinChange(new int[]{1, 3, 4}, 6, false));
    }
}
